# -*- coding: utf-8 -*-
import sys,re
p=sys.argv[1]; s=open(p,encoding='utf-8').read()
lines=s.split('\n')
for i,l in enumerate(lines):
    if l.startswith('      <li><b>Отчество дедушки Ивана Снимщикова</b>'):
        lines[i]='      <li><b>Дедушка Иван Федорович и его отец Федор:</b> год и место рождения Ивана; год рождения Федора и откуда он; вернулся ли Федор с войны; жили ли они в Москве или в Киеве. Знакомо ли имя Федор Васильевич, 1909 года, из Киева? <span class="why">Федоров Снимщиковых в военных базах несколько. Киевский Федор Васильевич вернулся с войны, курские кандидаты погибли. Эти ответы сразу покажут, кто из них наш.</span></li>'
    if l.startswith('      <li><b>Бабушка Галина Павловна:</b>'):
        lines[i]='      <li><b>Бабушка Галина Павловна:</b> год рождения; как звали её маму (Фекла?) и папу Павла, их годы жизни и откуда Павел родом; фамилия первого мужа мамы, погибшего на войне. Фото памятников в Фастове тоже подойдут.</li>'
    if l.startswith('      <li><b>Зайчук.</b>'):
        lines[i]='      <li><b>Зайчук.</b> Распространённая украинская фамилия: 139 документов на одних только Павлов Зайчуков. Никто из них не родился в Киевской области и не призван Фастовским РВК, так что Павел, видимо, приехал в Фастов из другой области. Ошибки в фамилии не видно.</li>'
open(p,'w',encoding='utf-8').write('\n'.join(lines)); print('ok')
